WITH src AS (SELECT *, ROUND(units / revenue, 2) AS revenue_per_unit FROM store_sales WHERE revenue < 2800), store_id_summary AS (SELECT store_id, DATE_TRUNC('MONTH', sale_date) AS sale_month, COUNT(DISTINCT revenue) AS unique_stores, MAX(sale_date) AS last_sale_date FROM src GROUP BY store_id, DATE_TRUNC('MONTH', sale_date)) SELECT * FROM store_id_summary ORDER BY 2, store_id LIMIT 10;
